export function buildGraph(posts, narratives, clusters, spread) {
  const nodes = [];
  const edges = [];

  for (const n of narratives || []) {
    nodes.push({ id: n.id, type: 'narrative', label: n.label, size: n.count || n.post_ids?.length || 0 });
  }

  for (const c of clusters || []) {
    nodes.push({ id: c.id, type: 'cluster', label: c.label, size: c.size || 0, suspicion_rank: c.suspicion_rank || 0 });
    if (c.narrative_id) {
      edges.push({ source: c.id, target: c.narrative_id, type: 'cluster_to_narrative' });
    }
  }

  for (const s of spread || []) {
    if (!nodes.find((x) => x.id === s.id)) {
      nodes.push({ id: s.id, type: 'spread', label: s.label, size: s.post_ids?.length || 0 });
    }
  }

  const postMap = new Map((posts || []).map((p) => [p.id, p]));

  for (const n of narratives || []) {
    for (const postId of n.post_ids || []) {
      const p = postMap.get(postId);
      if (!p) continue;
      const postNodeId = `post-${p.id}`;
      if (!nodes.find((x) => x.id === postNodeId)) {
        nodes.push({ id: postNodeId, type: 'post', label: p.title || p.id, subreddit: p.subreddit, author: p.author });
      }
      edges.push({ source: n.id, target: postNodeId, type: 'narrative_to_post' });
    }
  }

  return { nodes, edges };
}

export function searchAll(query, posts, narratives, clusters, spread) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return { posts: [], narratives: [], clusters: [], spread: [] };

  return {
    posts: (posts || []).filter((p) => `${p.title || ''} ${p.body || ''} ${p.subreddit || ''} ${p.author || ''}`.toLowerCase().includes(q)).slice(0, 20),
    narratives: (narratives || []).filter((n) => `${n.label || ''} ${(n.keywords || []).join(' ')}`.toLowerCase().includes(q)).slice(0, 20),
    clusters: (clusters || []).filter((c) => `${c.label || ''} ${(c.keywords || []).join(' ')} ${(c.subreddits || []).join(' ')}`.toLowerCase().includes(q)).slice(0, 20),
    spread: (spread || []).filter((s) => `${s.label || ''} ${(s.keywords || []).join(' ')} ${(s.subreddits || []).join(' ')}`.toLowerCase().includes(q)).slice(0, 20)
  };
}

